// Brand entrance: the supplied card artwork is animated as a perspective plane.
const studioHomePage=homePage;
homePage=function(){return `<section class="hp-intro" aria-label="한패스 크리에이티브 스튜디오"><nav class="hp-nav"><a href="#home" class="hp-wordmark">hanpass<span>CREATIVE STUDIO</span></a><button data-easy-nav="mine">내 작업 ↗</button></nav><div class="hp-hero"><div class="hp-eyebrow">YOUR IDEAS. OUR NEXT CHAPTER.</div><h1 class="hp-type"><span>Make it</span><span class="hp-outline">Hanpass.</span></h1><div class="hp-card-scene" aria-hidden="true"><div class="hp-card-tilt"><img class="hp-card-image" src="assets/hanpass-cards.png" alt="" fetchpriority="high"></div></div><div class="hp-bottom"><div><p>아이디어가 디자인이 되는 순간.</p><span>한패스의 다음 이야기를 직접 만들어 보세요.</span></div><button class="hp-start" id="hpStart">디자인 만들기 <span>↗</span></button></div><div class="hp-hero-foot"><span>HANPASS CREATIVE STUDIO — 01</span><button id="hpMotion" aria-pressed="false">모션 일시정지 Ⅱ</button><button id="hpScroll">크기 선택하기 ↓</button></div></div></section><div id="hpFormats">${studioHomePage()}</div>`};
const beforeIntroRender=render;
let introCleanup=()=>{};
let entrancePlayed=false;
render=function(){introCleanup();beforeIntroRender();const intro=document.querySelector('.hp-intro');document.body.classList.toggle('hp-home',!!intro);if(!intro)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let entranceTimer;
if(!entrancePlayed&&!reduced.matches){
  intro.classList.add('hp-entering');
  const veil=document.createElement('div');veil.className='hp-entry-veil';veil.setAttribute('aria-hidden','true');veil.innerHTML='<span class="hp-entry-light"></span>';intro.append(veil);
  entranceTimer=setTimeout(()=>{entrancePlayed=true;intro.classList.remove('hp-entering');veil.remove()},2600);
}
const tilt=intro.querySelector('.hp-card-tilt');let paused=reduced.matches;let frame=0;const motion=intro.querySelector('#hpMotion');function sync(){intro.classList.toggle('hp-paused',paused);document.body.classList.toggle('motion-stopped',paused);motion.textContent=paused?'모션 재생 ▷':'모션 일시정지 Ⅱ';motion.setAttribute('aria-pressed',String(paused));}sync();motion.onclick=()=>{paused=!paused;sync()};const move=e=>{if(paused)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=intro.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;tilt.style.transform=`rotateX(${-y*12}deg) rotateY(${x*20}deg) translate3d(${x*14}px,${y*10}px,0)`})};const reset=()=>{tilt.style.transform=''};intro.addEventListener('pointermove',move);intro.addEventListener('pointerleave',reset);const go=()=>{document.querySelector('#hpFormats').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'})};intro.querySelector('#hpStart').onclick=go;intro.querySelector('#hpScroll').onclick=go;const onReduced=()=>{paused=reduced.matches;sync();reset()};reduced.addEventListener('change',onReduced);introCleanup=()=>{clearTimeout(entranceTimer);cancelAnimationFrame(frame);intro.removeEventListener('pointermove',move);intro.removeEventListener('pointerleave',reset);reduced.removeEventListener('change',onReduced)};};
render();
